#!/bin/bash
cd /Users/justin/Code/Project-V/Video-Story1/research
export QWEN_DEADLINE=900
H="TOOL NOTE: web_search now falls back to GitHub and HuggingFace search (DuckDuckGo blocks bots), so use SHORT keyword queries (model names, e.g. 'kokoro', 'chatterbox tts', 'mlx-audio') and then fetch_page the GitHub README (raw.githubusercontent.com/<owner>/<repo>/main/README.md) or the HuggingFace model card (https://huggingface.co/<id>) to read licence, size and install commands. Cite URLs. Only state facts you read in tool results; write 'not found' otherwise. Keep the final report under 900 words."
python3 ~/.claude/bin/qwen_agent.py "$H TASK: pick a FREE open-licence LOCAL text-to-speech model for a warm gentle English female children's-storybook narrator on an Apple Silicon Mac (M5 Max, 64 GB, Python via uv). Check at least: hexgrad/Kokoro-82M with mlx-audio (github.com/Blaizzy/mlx-audio), Chatterbox (resemble-ai/chatterbox), Piper, Qwen3-TTS, Orpheus, Dia, F5-TTS, Sesame CSM, Parler-TTS. For each: licence of code and weights, size, runs on Mac GPU (MLX/MPS) or CPU, naturalness for storytelling, pace/emotion control, exact pip/uv install and a one-line run command. End with a RECOMMENDATION section: top 2 and the voice names to try." > tts_report.md 2> tts_err.log
python3 ~/.claude/bin/qwen_agent.py "$H TASK: the file /Users/justin/Code/Project-V/Video-Story1/research/draw_things_cli_help.txt is the real help text of draw-things-cli (read it with read_file first). The user wants to keep 4 painterly storybook characters (a girl, a boy, an older girl, a dragon) visually consistent across many images with Z Image Turbo (base for the look) using free local tools. Research: (1) can a LoRA trained with 'draw-things-cli train lora' on Z Image (turbo or base) or another base be applied with 'generate --config-json' loras? What dataset size, captions, steps, rank, learning rate and resolution are good for a single character LoRA on Z-Image (search HuggingFace/GitHub for Z-Image LoRA training guides, e.g. ostris ai-toolkit, DiffSynth, musubi-tuner)? (2) tips for consistent characters with image-to-image (--image with low strength) and fixed seeds. (3) tips for putting two character LoRAs in one picture. End with a RECOMMENDATION section." > consistency_report.md 2> consistency_err.log
python3 ~/.claude/bin/qwen_agent.py "$H TASK: LTX-2.3 (Lightricks, github.com/Lightricks/LTX-Video and LTX-2 repos, HuggingFace Lightricks/LTX-2.3) image-to-video: find official prompting guidance and known tips for animating a painted / watercolor illustration with people so faces and hands stay stable, painterly texture is kept, and motion is subtle (mist, leaves, cloth, hair); recommended frame count, resolution, steps, cfg for the distilled model. End with a RECOMMENDATION section and an example prompt template." > ltx_report.md 2> ltx_err.log
echo DONE > research_done.flag
